import {dateKey,validDate,moneyToMinor,expenseSummary,csv} from './core.mjs';
import {load,save,emptyState} from './storage.mjs';
const app=document.querySelector('#app');
let state,storageOK=true,month=dateKey().slice(0,7),editingExpense=null;
try{state=load();}catch(e){state=emptyState();storageOK=false;setTimeout(()=>toast(e.message),100);}
const uid=()=>crypto.randomUUID();
function top(){return '<div class="page-top"><div><div class="eyebrow">ПОНЯТНЫЕ РАСХОДЫ КАЖДЫЙ ДЕНЬ</div><h1>Счёт <span class="muted">/ трекер расходов</span></h1></div><div class="actions"><a class="btn secondary" href="docs/specification.md">ТЗ и кейс</a><button class="secondary" data-action="export">Экспорт CSV ↓</button></div></div>';}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rub=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2}).format(n/100);
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.style.display='block';clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>t.style.display='none',6000);}
function commit(update){if(!storageOK){toast('Хранилище недоступно. Скачайте сохранённые данные через инструменты браузера перед восстановлением.');return false;}const next=structuredClone(state);update(next);try{save(next);state=next;return true;}catch{toast('Не удалось сохранить данные: проверьте свободное место и разрешения браузера.');return false;}}
function download(name,data,type='text/csv;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const localNote='<p class="local-status">Локальное сохранение · этот браузер · без облачной синхронизации. Экспортируйте данные для резервной копии.</p>';
const categories=['Продукты','Транспорт','Дом','Здоровье','Досуг','Другое'];
function expensePage(){const summary=expenseSummary(state.expenses,month),edit=state.expenses.find(x=>x.id===editingExpense),rows=state.expenses.filter(x=>x.date.startsWith(month)).sort((a,b)=>b.date.localeCompare(a.date));app.innerHTML=top('money')+`<div class="stats"><div class="stat"><span>РАСХОДЫ МЕСЯЦА</span><strong>${rub(summary.total)}</strong></div><div class="stat"><span>ОПЕРАЦИЙ</span><strong>${summary.count}</strong></div><div class="stat"><span>СРЕДНИЙ РАСХОД</span><strong>${rub(summary.count?Math.round(summary.total/summary.count):0)}</strong></div></div><div class="workspace"><div><section class="panel"><div class="row"><h2>Журнал расходов</h2><div><label for="month" style="margin:0" class="small">Месяц</label><input id="month" type="month" value="${month}"></div></div>${rows.length?rows.map(x=>`<article class="entry row"><div><strong>${esc(x.note||x.category)}</strong><div class="small muted">${esc(x.category)} · ${x.date.split('-').reverse().join('.')}</div></div><div class="actions"><strong>${rub(x.amount)}</strong><button class="icon-button" data-action="edit-expense" data-id="${x.id}">Изменить</button><button class="icon-button" data-action="delete-expense" data-id="${x.id}" aria-label="Удалить расход ${esc(x.note||x.category)}">×</button></div></article>`).join(''):'<div class="empty">В этом месяце пока нет расходов.<br>Добавьте первую покупку.</div>'}</section><section class="panel"><h2>По категориям</h2>${Object.entries(summary.categories).sort((a,b)=>b[1]-a[1]).map(([cat,n])=>`<div class="bar-row"><div class="row"><span>${esc(cat)}</span><span>${rub(n)} · ${Math.round(n/summary.total*100)}%</span></div><div class="track"><i style="width:${n/summary.total*100}%"></i></div></div>`).join('')||'<p class="small muted">Разбивка появится после первой операции.</p>'}</section>${localNote}</div><aside><section class="panel"><h2>${edit?'Изменить расход':'Новый расход'}</h2><form id="expense-form"><label for="amount">Сумма, ₽</label><input id="amount" name="amount" inputmode="decimal" required placeholder="0,00" value="${edit?(edit.amount/100).toFixed(2):''}"><label for="category">Категория</label><select id="category" name="category">${categories.map(c=>`<option ${edit?.category===c?'selected':''}>${c}</option>`).join('')}</select><label for="expense-date">Дата</label><input id="expense-date" name="date" type="date" required max="9999-12-31" value="${edit?.date||dateKey()}"><label for="note">Комментарий</label><input id="note" name="note" maxlength="120" placeholder="Например, обед" value="${esc(edit?.note||'')}"><button>${edit?'Сохранить изменения':'Добавить расход +'}</button>${edit?'<button type="button" class="secondary" data-action="cancel-expense">Отмена</button>':''}<div class="error" role="alert"></div></form></section><p class="notice">Все суммы — в рублях. Категории и итоги обновляются после сохранения. CSV содержит расходы выбранного месяца.</p></aside></div>`;}
app.addEventListener('change',e=>{if(e.target.id==='month'&&/^\d{4}-\d{2}$/.test(e.target.value)){month=e.target.value;expensePage();}});
app.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(form.id!=='expense-form')return;const v=Object.fromEntries(new FormData(form));try{if(!validDate(v.date))throw Error('Укажите корректную дату.');if(!categories.includes(v.category))throw Error('Выберите категорию из списка.');if(v.note.length>120)throw Error('Комментарий должен быть не длиннее 120 символов.');const item={id:editingExpense||uid(),amount:moneyToMinor(v.amount),date:v.date,category:v.category,note:v.note.trim()};if(commit(s=>{const index=s.expenses.findIndex(x=>x.id===item.id);if(index<0)s.expenses.push(item);else s.expenses[index]=item;})){editingExpense=null;month=item.date.slice(0,7);expensePage();}}catch(err){form.querySelector('.error').textContent=err.message;}});
app.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const {action,id}=button.dataset;
if(action==='edit-expense'){editingExpense=id;expensePage();document.querySelector('#amount').focus();}
else if(action==='cancel-expense'){editingExpense=null;expensePage();}
else if(action==='delete-expense'){if(confirm('Удалить этот расход?')&&commit(s=>s.expenses=s.expenses.filter(x=>x.id!==id))){if(editingExpense===id)editingExpense=null;expensePage();}}
else if(action==='export'){const rows=[['Дата','Категория','Комментарий','Сумма RUB'],...state.expenses.filter(x=>x.date.startsWith(month)).map(x=>[x.date,x.category,x.note,(x.amount/100).toFixed(2)])];download('schet-'+month+'.csv',csv(rows));toast('CSV подготовлен. Проверьте папку загрузок.');}});
window.addEventListener('storage',()=>{try{state=load();storageOK=true;expensePage();}catch(e){storageOK=false;toast(e.message);}});
expensePage();
